#' Tokenizer for a corpus object
#'
#' This function takes a "corpus" object as generated by [quanteda::corpus()]
#' and returns a list of tokens. In a first step, the user can decide whether to
#' remove punctuation, symbols, numbers, url, or separators. In a second step,
#' the terms in the corpus are set to lower case, stemmed, and stop words, as
#' well as a pre-defined set of terms, are removed. This function is a wrapper
#' around [quanteda::tokens()] and other `quanteda::tokens_*()` functions.
#'
#' @param corpus A corpus object as returned by [quanteda::corpus()].
#' @param remove_punct A logical indicating whether punctuation should be
#' removed from the corpus (default is `TRUE`, see `?quanteda::corpus()` for
#' more details).
#' @param remove_symbols A logical indicating whether symbols should be removed
#' from the corpus (default is `TRUE`, see `?quanteda::corpus()` for more
#' details).
#' @param remove_numbers A logical indicating whether numbers should be removed
#' from the corpus (default is `FALSE`, see `?quanteda::corpus()` for more
#' details).
#' @param remove_url A logical indicating whether url should be removed from the
#' corpus (default is `TRUE`, see `?quanteda::corpus()` for more details).
#' @param remove_separators A logical indicating whether separators should be
#' removed from the corpus (default is `TRUE`, see `?quanteda::corpus()` for
#' more details).
#'
#' @return A list of tokens of class `<tokens>`.

tokens_snsf <- function(
  corpus,
  remove_punct = TRUE,
  remove_symbols = TRUE,
  remove_numbers = TRUE,
  remove_url = TRUE,
  remove_separators = TRUE
) {
  terms <- quanteda::tokens(
    corpus,
    remove_punct = remove_punct,
    remove_symbols = remove_symbols,
    remove_numbers = remove_numbers,
    remove_url = remove_url,
    remove_separators = remove_separators,
  ) |>
    quanteda::tokens_tolower() |>
    quanteda::tokens_wordstem() |>
    quanteda::tokens_remove(
      # fmt: skip
      pattern = c(
        quanteda::stopwords("en"),
        # Most frequent terms in research projects
        "project", "research", "can", "studi", "new", "make", "use", "aim",
        "result", "goal", "non", "particular", "may",
        # Remove frequent adverbs
        "also", "howev", "thus", "within", "like", "often", "toward", "whether",
        "yet", "among", "therefor", "across", "also", "besid", "instead",
        "likewis", "moreov", "nevertheless", "yet",
        # Remove Latin abbreviations
        "i.e", "et", "al", "e.g",
        # Remove single letters
        letters,
        # Remove typed single digits
        "one", "two", "three", "four", "five",
        "six", "seven", "height", "nine", "ten"
      )
    )

  terms
}

#' Load `stm` topics models saved locally
#'
#' @param path String with the path where are saved the models. It is important
#' that only `stm` topic models are included in the folder.
#' @param base_name String with the unique identifier name of the models in the
#' folder.
#' @param range Numeric vector of length 2 indicating the model to include. If
#' the number of topics of the model is in the range, the model is loaded.
#' @param dfm The document-feature matrix used to create the topic models
#' loaded.
#'
#' @returns A list of topic models, using the name of the files loaded to name
#' the models in the list.

load_topic_models_local <- function(
  path,
  base_name,
  range = c(2, Inf),
  dfm = NULL
) {
  # Listing all the model files in the folder
  files <- list.files(path, pattern = paste0("^", base_name))
  # Extract the number of topics from the model file names
  k_in_files <- str_extract(files, "k_(\\d+).rds$", group = 1)
  # Determine the models that are in the range
  files_to_keep <- as.numeric(k_in_files) >= range[1] &
    as.numeric(k_in_files) <= range[2]
  # Subset the models to keep
  models_path <- files[files_to_keep]
  # Extract the name of the models to keep
  models_names <- str_extract(models_path, "^.+(k_\\d+)\\.rds$", group = 1)
  # Read the RDS files with the models to load
  models <- map(file.path(path, models_path), read_rds)
  names(models) <- models_names

  models
}

#' Evaluate Structural Topic Models
#'
#' @description
#' This function take a list of Structural Topic Models (a list of models with
#' different value for K/number of topics) as produced by [stm::stm()] and
#' evaluates the exclusivity and semantic coherence of the words in the topics,
#' as well as the held-out likelihood, and the residuals.
#'
#' @param models The topic model(s) of class <stm> (as outputted by
#' [stm::stm()]).
#' @param dfm A sparse document-feature matrix from which the models passed to
#' `models` were build from.
#' @param n_held_out An integer (default is `100L`) indicating the number of
#' time the held-out likelihood is to be repeated to have better evaluation (see
#' [stm::make.heldout()] for more details).
#' @param file A string with the location of the file to save with the output of
#' the function. Default is `NULL` (nothing is saved). The extension must be
#' `.rds` and the path to the file must exist.
#'
#' @return Returns a data.frame where each row is a model present passed to the
#' `models` argument and each column represent an evaluation metric. The metrics
#' returned are:
#' * **k**: integer with the number of topics in the model.
#' * **exclusivity**: numeric value indicating the extent to which the words in
#' the topics are frequent and exclusive.
#' * **semantic_coherence**: numeric value indicating the extent to which the
#' words in the topics are semantically coherent (words which are most probable
#' under a topic should co-occur within the same document).
#' * **eval_heldout**: numeric value with the evaluation of held-out likelihood.
#' * **residuals**: numeric value with the multinomial dispersion of the model
#' residuals.

eval_stm_model <- function(models, dfm, n_held_out = 100L, file = NULL) {
  # Check the object passed to `models`
  if (inherits(models, "list")) {
    all_stm <- all(unlist(lapply(models, \(x) inherits(x, "STM"))))

    if (!all_stm) {
      cli::cli_abort(
        paste0(
          "The object passed to {.var models} must of a model (or a list of ",
          "of  models) of class {.cls STM}."
        )
      )
    }
  } else if (inherits(models, "STM")) {
    models <- list(models)
  }
  # Check the object passed to `dfm`
  if (class(dfm) != "dfm") {
    cli::cli_abort(
      "The object passed to {.var dfm} must be of class {.cls dfm}."
    )
  }

  # Repeating `n_held_out` times the computation of the held-out likelihood for
  # the dfm object.
  held_out_dat <- purrr::map(
    1:n_held_out,
    \(x) stm::make.heldout(dfm),
    .progress = "Preparing held-out for the STM model(s)..."
  )
  cli::cli_alert_success("Held-out (preparation)")

  # For each model, evaluate the held-out likelihood for each partition created
  # before it is averaged later (see below).
  eval_heldout <- purrr::map(
    models,
    \(x) {
      unlist(
        map(
          held_out_dat,
          \(y) stm::eval.heldout(x, y$missing)$expected.heldout
        )
      )
    },
    .progress = "Evaluate held-out likelihood for the STM model(s)..."
  )
  cli::cli_alert_success("Held-out (evaluation)")

  # For each model, compute the exclusivity metric of a model (run
  # `?exclusivity` for more details).
  exclusivity <- purrr::map(
    models,
    \(x) stm::exclusivity(x),
    .progress = "Calculate the exclusivity metric for the STM model(s)..."
  )
  cli::cli_alert_success("Exclusivity")

  # For each model, compute the semantic coherence of a model (run
  # `?semanticCoherence` for more details).
  semantic_coherence <- purrr::map(
    models,
    \(x) stm::semanticCoherence(x, dfm),
    .progress = "Calculate the semantic coherence for the STM model(s)..."
  )
  cli::cli_alert_success("Semantic coherence")

  # For each model, check the dispersion of residuals  (run
  # `?checkResiduals` for more details).
  residuals <- map(
    models,
    \(x) stm::checkResiduals(x, dfm),
    .progress = "Compute the residuals of the STM model(s)..."
  )
  cli::cli_alert_success("Residuals")

  # Combine the all the checks into a single tibble where each row is a model
  # and columns are the objects returned by the checks.
  res <- dplyr::tibble(
    k = as.vector(purrr::map_int(models, \(x) x$settings$dim$K)),
    exclusivity = exclusivity,
    semantic_coherence = semantic_coherence,
    heldout_likelihood = eval_heldout,
    residuals = residuals
  )

  attr(res, "stm_eval") <- TRUE

  if (!is.null(file)) {
    con <- file(file)
    on.exit(close(con), add = TRUE)
    saveRDS(res, con, version = 2, refhook = NULL, ascii = FALSE)
  }

  res
}

#' Get tidy top terms from a Structural Topic Model
#'
#' This functions takes a Structural Topic Model and extracts the top terms
#' characterizing the topics present in the model the most.
#'
#' @param model topic model of class (as outputted by `stm::stm()`).
#' @param n A positive integer indicating the number of top terms per topic to
#' return.
#' @param score	A string indicating the type of score used to extract the top
#' terms (see `?stm::labelTopics()`] for more details about the different
#' scores).
#' @param format A string indicating the format of the output table:
#' * **wide**: Rows are topics and columns are top terms.
#' * **long**: Long table where a row is a single top term for a single topic.
#' * **wide_by_topic**: Transposition of "wide" where each row is a top term
#' level (1 to n) and each column is a topic.
#' * **string**: Similar to "wide" except that all top terms are collapsed into
#' a single string with coma-separator.
#' @return A data.frame with top terms from a Structural Topic Model.

get_stm_top_terms <- function(
  model,
  n = 10,
  score = c("prob", "frex", "score", "lift"),
  format = c("wide", "long", "wide_by_topic", "string")
) {
  score <- match.arg(score)
  format <- match.arg(format)

  k <- model$settings$dim$K

  top_terms <- stm::labelTopics(model, topics = 1:k, n = n)[[score]] |>
    dplyr::as_tibble(.name_repair = ~ paste0("term_", 1:n)) |>
    dplyr::mutate(topic = 1:k) |>
    dplyr::relocate(topic)

  if (format == "string") {
    res <- top_terms |>
      tidyr::unite(col = "terms", sep = ", ", tidyr::starts_with("term_"))
  } else if (format == "wide") {
    res <- top_terms
  } else if (format == "long") {
    res <- top_terms |>
      tidyr::pivot_longer(
        cols = tidyr::starts_with("term"),
        values_to = "term",
        names_to = "name"
      ) |>
      dplyr::select(-name)
  } else if (format == "wide_by_topic") {
    res <- top_terms |>
      dplyr::mutate(topic = paste0("Topic ", topic)) |>
      tidyr::pivot_longer(
        cols = tidyr::starts_with("term"),
        values_to = "term",
        names_to = "Top term"
      ) |>
      tidyr::pivot_wider(
        names_from = topic,
        values_from = term
      ) |>
      mutate(`Top term` = gsub("_", " ", `Top term`))
  }

  res
}

#' Estimate and tidy the covariate effect of a structural topic model
#'
#' For more details about estimating effect for a structural topic model, see
#' `?estimateEffect`.
#'
#' @param model The STM object from which to extract and tidy the effect.
#' @param dfm The dfm object with which the structural topic model passed to
#' the `model` argument has been built.
#' @param cov The name of the covariate variable.
#' @param nsims The number of draws when estimating the effect (default is 100).
#'
#' @returns Tibble with the estimate mean estimated effects. A row is a single
#' estimate effect for each combination of topic and covariate level.

tidy_stm_effects <- function(model, dfm, cov, nsims = 100) {
  # Number of topics in the model
  k <- model$settings$dim$K

  # Get the initial call for covariates, but as character instead of formula
  call_cov <- paste0(stm_model$settings$covariates$formula, collapse = "")

  # Estimate effects using function from the `stm` package that operates
  # directly on STM objects.
  estimated_effects <- stm::estimateEffect(
    # Set the formula with all the topic on left-hand side and the covariate as
    # factor on the right-hand side.
    formula = as.formula(paste0("1:", k, call_cov)),
    stmobj = model,
    metadata = quanteda::docvars(dfm),
    nsims = nsims,
    uncertainty = "Global"
  )

  # Plot the estimated effects, but without outputting the plot so we can
  # extract the mean estimated effects for each level of the covariate.
  plot_estimated_effects <- stm::plot.estimateEffect(
    estimated_effects,
    covariate = cov,
    topics = 1:k,
    nsims = nsims,
    # We just want the returned values, not the plot!
    omit.plot = TRUE
  )

  # To tidy the estimated effects, we loop over the topics and mean estimated
  # effects (a list of 25 vectors, where each element in the list is a topic and
  # each element in sub-vector is the factor level). At each
  # step we extract the topic and the estimates vector, assuming the estimates
  # correspond to the levels in `plot_estimated_effects$uvals`.
  tidy_effects <- purrr::pmap(
    list(
      plot_estimated_effects$topics,
      plot_estimated_effects$means
    ),
    \(x, y) {
      dplyr::tibble(topic = x, cov = plot_estimated_effects$uvals, mean = y)
    }
  ) |>
    # We combine everything in a long tibble and rename the covariate column
    # with its original name
    purrr::list_rbind() |>
    dplyr::rename_with(\(x) cov, tidyselect::matches("cov"))

  tidy_effects
}